import crypto from 'crypto';
import { EventEmitter } from 'events';

interface AuthToken {
  serviceId: string;
  nonce: Buffer;
  timestamp: number;
  hmac: Buffer;
}

interface SessionState {
  sharedSecret: Buffer;
  counter: number;
  active: boolean;
}

class CryptoSessionPool {
  private sessions: Map<string, SessionState> = new Map();
  private pendingCallbacks: Map<string, ((state: SessionState) => void)[]> = new Map();
  private emitter = new EventEmitter();

  constructor(private masterKey: Buffer) {
    this.emitter.on('sessionReady', (serviceId: string) => {
      this.dispatchPending(serviceId);
    });
  }

  async initSession(serviceId: string): Promise<void> {
    const derivedKey = crypto.pbkdf2Sync(
      this.masterKey, 
      Buffer.from(serviceId, 'utf8'), 
      100000, 32, 'sha512'
    );
    const state: SessionState = {
      sharedSecret: derivedKey,
      counter: 0,
      active: true
    };
    this.sessions.set(serviceId, state);
    this.emitter.emit('sessionReady', serviceId);
  }

  async rotateKey(serviceId: string): Promise<void> {
    const current = this.sessions.get(serviceId);
    if (!current) return;

    current.active = false;

    const newKey = crypto.pbkdf2Sync(
      current.sharedSecret,
      Buffer.from(`rotate-${current.counter}`, 'utf8'),
      100000, 32, 'sha512'
    );

    // Clear old secret material
    current.sharedSecret.fill(0);

    const newState: SessionState = {
      sharedSecret: newKey,
      counter: current.counter + 1,
      active: true
    };

    this.sessions.set(serviceId, newState);
    this.emitter.emit('sessionReady', serviceId);
  }

  withSession(serviceId: string, callback: (state: SessionState) => void): void {
    const session = this.sessions.get(serviceId);
    if (session && session.active) {
      callback(session);
    } else {
      if (!this.pendingCallbacks.has(serviceId)) {
        this.pendingCallbacks.set(serviceId, []);
      }
      this.pendingCallbacks.get(serviceId)!.push(callback);
    }
  }

  private dispatchPending(serviceId: string): void {
    const callbacks = this.pendingCallbacks.get(serviceId);
    if (!callbacks || callbacks.length === 0) return;

    const session = this.sessions.get(serviceId);
    if (!session) return;

    this.pendingCallbacks.delete(serviceId);
    callbacks.forEach(cb => cb(session));
  }
}

class CrossServiceAuthenticator {
  private pool: CryptoSessionPool;
  private verificationCache: Map<string, { token: AuthToken; sessionRef: SessionState }> = new Map();

  constructor(masterKey: Buffer) {
    this.pool = new CryptoSessionPool(masterKey);
  }

  async registerService(serviceId: string): Promise<void> {
    await this.pool.initSession(serviceId);
  }

  generateToken(serviceId: string): Promise<AuthToken> {
    return new Promise((resolve, reject) => {
      this.pool.withSession(serviceId, (session) => {
        const nonce = crypto.randomBytes(16);
        const timestamp = Date.now();
        const counter = session.counter++;

        const payload = Buffer.concat([
          Buffer.from(serviceId, 'utf8'),
          nonce,
          Buffer.alloc(8).fill(0) // timestamp placeholder
        ]);
        payload.writeBigInt64BE(BigInt(timestamp), serviceId.length + 16);

        const hmac = crypto.createHmac('sha256', session.sharedSecret)
          .update(payload)
          .digest();

        const token: AuthToken = { serviceId, nonce, timestamp, hmac };

        // Cache for deferred verification - stores reference to session
        this.verificationCache.set(
          nonce.toString('hex'),
          { token, sessionRef: session }
        );

        resolve(token);
      });
    });
  }

  async verifyTokenDeferred(nonceHex: string): Promise<boolean> {
    const cached = this.verificationCache.get(nonceHex);
    if (!cached) return false;

    const { token, sessionRef } = cached;

    // Uses the stored session reference for verification
    // After rotateKey(), sessionRef.sharedSecret has been zeroed out
    // but sessionRef still points to the old (zeroed) object
    const payload = Buffer.concat([
      Buffer.from(token.serviceId, 'utf8'),
      token.nonce,
      Buffer.alloc(8).fill(0)
    ]);
    payload.writeBigInt64BE(BigInt(token.timestamp), token.serviceId.length + 16);

    const expectedHmac = crypto.createHmac('sha256', sessionRef.sharedSecret)
      .update(payload)
      .digest();

    return crypto.timingSafeEqual(expectedHmac, token.hmac);
  }

  async rotateServiceKey(serviceId: string): Promise<void> {
    await this.pool.rotateKey(serviceId);
  }

  clearCache(nonceHex: string): void {
    this.verificationCache.delete(nonceHex);
  }
}

export { CrossServiceAuthenticator, CryptoSessionPool, AuthToken };
